FROM Matches m
JOIN Players p ON m.player_of_match_id = p.player_id
WHERE m.match_winner IS NOT NULL
  AND (
    (m.match_winner = m.team1 AND p.player_id IN (
      SELECT player_id FROM PlayerInMatch WHERE match_id = m.match_id AND team_name = m.team2
    ))
    OR
    (m.match_winner = m.team2 AND p.player_id IN (
      SELECT player_id FROM PlayerInMatch WHERE match_id = m.match_id AND team_name = m.team1
    ))
  );

